def the_three_pilgrimages(case, data):
    """F4 — Deut 16:16-17 — THE LINE three_pilgrimages_declared writing three_pilgrimages_commanded (a STATUS) and empty_appearance_barred (a BLOCK); the exempt list, the two amounts, the gift of the hand PARAMETERS from the answer sheet (Mishnah Chagigah 1:1, 1:2, 1:5); the appearing by CALL (calendar, erection)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_three_times':
        ink('16:16', '"THREE TIMES A YEAR all your males shall appear before the LORD your God in the place which He will choose" — the parser\'s [3] %s ("three" spelled full — the diff with Exodus 34:23 %s); Exodus 34:23\'s eight in order, 23:17\'s seven %s; 2 Chronicles 8:13 the one other verse with the three names in order (asserted at the reading)' % (PARSE[16][0], DIFF(D16(16), ('Exod', 34, 23))[0], (TWIN['16:16 vs Exod 34:23'], TWIN['16:16 vs Exod 23:17'])))
        move('the Sifrei 143:1-2 (read whole at the reading); cold_run_calendar (CALL) — CA.pilgrimage(able_male) = %s; the one database — appearance_owed on %s' % (CA_MALE, APPEAR_SCAN[0]), "THE THREE TIMES — 'times' the seasons (143:1 — Onkelos 'three times in the year'), the appearing (143:2 — as He comes to see, He comes to be seen: the two eyes); the able male owes the three appearings by CALL (appearance_owed the calendar's heaven entry on its case world, NONE on the tape UNMOVED): THE STATUS three_pilgrimages_commanded the chapter's addition — the place")
        dat('THE WRITE three_pilgrimages_commanded — a STATUS on israel_people at the counter\'s day (DH2); the exam\'s person the able man who ascends three times to the place — accepted')
        return out("the three times (16:16) — all the males appear three times at the place (the Sifrei 143:1-2; calendar.pilgrimage('able_male') %s by CALL): THE WRITE three_pilgrimages_commanded, a STATUS on Israel at the chapter's own day; the able man who ascends thrice accepted" % (CA_MALE,), ['three_pilgrimages_commanded'])
    if ask == 'who_appears':
        ink('16:16', '"ALL YOUR MALES" — "your males" %s; the phrase "all your males shall appear" three in the Bible (Exodus 23:17, 34:23, here — asserted at the reading)' % ([x for x in W16(16) if x == 'זכורך'],))
        move('the Sifrei 143:3-5 (read whole at the reading — the Mishnah\'s minor inside the spine); MISHNAH CHAGIGAH 1:1 (read whole at the design — THE EXAM ROW); cold_run_calendar (CALL) — woman %s, lame %s, one-eyed %s' % (CA_WOMAN, CA_LAME, CA_EYE), "WHO APPEARS — all are obligated in the appearance except the deaf-mute, the imbecile, the minor, the tumtum, the hermaphrodite, women, unfreed slaves, the lame, the blind, the sick, the old and one who cannot ascend on foot; THE MINOR — the House of Shammai: one who cannot ride on his father's shoulders; the House of Hillel: one who cannot hold his father's hand and ascend, 'three regalim' read at the feet: A PARAMETER with the list and the minor's two arms; the calendar's exempt arms by CALL")
        dat('THE PARAMETER the_exempt_from_appearing (the twelve exempt, the minor two arms); the exam\'s person the woman at the feast — exempt; the child who can hold his father\'s hand — obligated by Hillel\'s arm')
        return out("who appears (16:16) — all obligated except the twelve exempt, the minor by the father's shoulders (Shammai) or hand (Hillel) — Mishnah Chagigah 1:1 read whole (the Sifrei 143:3-5; calendar.pilgrimage by CALL: the woman %s): THE PARAMETER the_exempt_from_appearing; the woman at the feast exempt" % (CA_WOMAN,), ['exempt'])
    if ask == 'the_order_of_the_names':
        ink('16:16', '"at the feast of unleavened bread, at the feast of weeks and at the feast of booths" — the three names in order; "and at the feast of booths" %s' % (P('ובחג', 'הסכות', books=None),))
        move('the Sifrei 143:7 (read whole at the reading)', "THE ORDER OF THE THREE NAMES READ AS A CLOCK — R. Simeon: no need to say booths, the verse's own subject; why weeks and booths? one does not transgress 'do not delay' (23:22 ahead) until the whole year's pilgrimages have passed in order: THE DELAY'S CLOCK a DATA row (Mishnah Rosh Hashanah 1:1, 4a owed); 2 Chronicles 8:13 the run's case")
        dat('the delay\'s clock a DATA row (the_delays_clock — three feasts in order from the vow); the exam\'s person the vower whose two feasts passed out of order — accepted, not yet in delay')
        return out("the order of the names (16:16) — the delay's clock three feasts in order (the Sifrei 143:7; 2 Chronicles 8:13 the run's case): the vower whose two feasts passed out of order accepted, not yet in delay", ['accepted'])
    if ask == 'not_empty':
        ink('16:16', '"AND NONE SHALL APPEAR BEFORE THE LORD EMPTY" — the one seat of the form (Exodus 23:15 and 34:20 "they shall not appear before Me empty" the plural twins %s); Onkelos "empty" one seat' % (ER_EMPTY2,))
        move('the Sifrei 143:8 (read whole at the reading); cold_run_erection (CALL) — ER.repeats(empty_where_it_stands) = %s; the one database — appearance_gift_owed on %s' % (ER_STAND, APPEAR_SCAN[1]), "NOT EMPTY — the appearance burnt offering (143:8); 'empty'/'empty' from the appearance offering the standing liability (Bekhorot 51b — the erection's cell by CALL; appearance_gift_owed the erection's debit on its case world, NONE on the tape UNMOVED): THE BLOCK empty_appearance_barred the chapter's third seat of the clause")
        dat('THE WRITE empty_appearance_barred — a BLOCK on israel_people at the counter\'s day (DH2); the exam\'s person the pilgrim who appears without an offering — barred from it')
        return out("not empty (16:16) — the appearance offering owed at the appearing (the Sifrei 143:8; erection.repeats %s by CALL): THE WRITE empty_appearance_barred, a BLOCK on Israel at the chapter's own day; the pilgrim without an offering barred from it" % (ER_STAND,), ['empty_appearance_barred'])
    if ask == 'the_two_amounts':
        ink('16:16-17', '"none shall appear … empty; each man as the gift of his hand" — the measure the answer sheet\'s')
        move('the Sifrei 143:8 (read whole at the reading); MISHNAH CHAGIGAH 1:2 (read whole at the design — THE EXAM ROW); cold_run_erection (CALL) — ER.repeats(appearance_amounts) = %s' % (ER_AMOUNTS,), "THE TWO AMOUNTS — the House of Shammai: the appearance two silver and the festival offering a ma'ah; the House of Hillel: the appearance a ma'ah and the festival offering two silver: A PARAMETER with both arms (the erection's DATA row the same pair by CALL)")
        dat('THE PARAMETER the_two_amounts (Shammai / Hillel); the exam\'s person the pilgrim whose appearance offering is worth a ma\'ah — accepted by Hillel\'s arm')
        return out("the two amounts (16:16-17) — the appearance two silver and the festival offering a ma'ah (Shammai), the reverse (Hillel) — Mishnah Chagigah 1:2 read whole (erection's %s by CALL): THE PARAMETER the_two_amounts; the ma'ah appearance accepted by Hillel's arm" % (ER_AMOUNTS,), ['accepted'])
    if ask == 'the_gift_of_the_hand':
        ink('16:17', '"EACH MAN AS THE GIFT OF HIS HAND, according to the blessing of the LORD your God which He has given you" — the verse %s; 12:15\'s six tokens shared in order %s' % (W16(17)[:3], TWIN['16:17 vs 12:15']))
        move('the Sifrei 143:9 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew); MISHNAH CHAGIGAH 1:5 (read whole at the design — THE EXAM ROW)', "THE GIFT OF THE HAND — one with many eaters and little property brings many peace offerings and few burnt offerings; much property and few eaters — many burnt and few peace; both few — the ma'ah and the two silver; both many — 'each man as the gift of his hand, according to the blessing': A PARAMETER with the four cases")
        dat('THE PARAMETER the_gift_of_the_hand (the four cases); the exam\'s person the man of many eaters and little property who brings many peace offerings — accepted')
        return out("the gift of the hand (16:17) — many eaters and little property: many peace offerings and few burnt; the reverse reversed; both few the minimums; both many as his hand — Mishnah Chagigah 1:5 read whole (the Sifrei 143:9): THE PARAMETER the_gift_of_the_hand; the man of many eaters accepted", ['accepted'])
    if ask == 'the_guard_of_the_land':
        ink('16:16', '"all your males shall appear" — while every male goes up, who guards the land? (the Sifrei 52:4 on 11:25, citing 16:16 — the outside row reread whole)')
        move('the Sifrei 52:4 (reread whole at the reading); cold_run_erection (CALL) — ER.repeats(warranty_read) = %s' % (ER_GRAZE,), "THE GUARD OF THE LAND — 'no man shall covet your land when you go up' (Exodus 34:24 — pilgrim_land_guarded the erection's heaven entry; 'your cow grazes in the meadow and no beast harms it' — Pesachim 8b by the erection's cell): the warranty of the pilgrimage, a DATA row")
        dat('the guard of the land a DATA row (the_guard_of_the_land — Exodus 34:24 by CALL); the exam\'s person the householder who leaves his field to appear — accepted, the land guarded')
        return out("the guard of the land (16:16) — 'no man shall covet your land when you go up' (the Sifrei 52:4; erection.repeats %s by CALL): the householder who leaves his field to appear accepted" % (ER_GRAZE,), ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_judges_in_every_gate(case, data):
    """F5 — Deut 16:18-20 — THE LINE judges_in_every_gate_commanded writing judges_and_officers_commanded and justice_pursuit_commanded (STATUSES), judgment_wresting_barred and person_respecting_barred (BLOCKS) and bribe_barred (its FIRST entry); the three tiers and the acquittal final PARAMETERS; the courts by CALL (exodus_story, opening_speech, ordinances, holiness, second_tablets)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_court_for_all_israel':
        ink('16:18', '"JUDGES AND OFFICERS YOU SHALL SET FOR YOURSELF" — the pair\'s one seat in the Bible %s; the participles %s; 1:16 shares two in order, Exodus 18:21 one %s' % (P('שפטים', 'ושטרים', books=None), W16(18)[:2], (TWIN['16:18 vs 1:16'],)))
        move('the Sifrei 144:1 (read whole at the reading); cold_run_exodus_story (CALL) — ES.jethro(judges) = %s, (sanhedrin_sizes) = %s; the one database — courts_established on %s, judges_charged on %s' % (ES_JUDGES, ES_SIZES, COURTS_SCAN, JUDGES_SCAN), "THE COURT FOR ALL ISRAEL FROM 'FOR YOURSELF' (144:1 — the first tier; the two nouns two offices, each read alone); Exodus 18:25's founding on the tape (courts_established ONE on Israel — 78,600 judges over the four denominations) and 1:16's charge (judges_charged ONE on the court) the references, never a second write: THE STATUS judges_and_officers_commanded")
        dat('THE WRITE judges_and_officers_commanded — a STATUS on israel_people at the counter\'s day (DH2); the exam\'s person the community that appoints a court for all Israel — accepted')
        return out("the court for all Israel (16:18) — judges and officers 'for yourself' (the Sifrei 144:1; exodus_story.jethro %s judges, the sizes %s by CALL): THE WRITE judges_and_officers_commanded, a STATUS on Israel at the chapter's own day; the community that appoints the court accepted" % (ES_JUDGES, ES_SIZES), ['judges_and_officers_commanded'])
    if ask == 'the_three_tiers':
        ink('16:18', '"in ALL YOUR GATES which the LORD your God gives you, TRIBE BY TRIBE" — "in all your gates" the book\'s four %s; "your tribes" %s' % (P('בכל', 'שעריך', books=None), [x for x in W16(18) if x == 'לשבטיך']))
        move('the Sifrei 144:2-5 (read whole at the reading); cold_run_ordinances (CALL) — OR.courts(twenty_three) = %s; cold_run_opening_speech (CALL) — OP(the_court_of_three) = %s' % (OR_23, OP_THREE[:50]), "THE THREE TIERS — the court for all Israel (144:1), every tribe's court (144:2-3), every city's court in its gate (144:4); 'in all your gates' compares the great Sanhedrin to the small: as the great judges and executes, so the small (144:5 — Mishnah Sanhedrin 1:1, 1:4 the seventy-one and the twenty-three by CALL; the court of three for money): A PARAMETER the_three_tiers")
        dat('THE PARAMETER the_three_tiers (seventy-one for all Israel, twenty-three for the tribe and the city, three for money — the answer sheet by CALL); the exam\'s person the city court of twenty-three that tries a capital case — accepted')
        return out("the three tiers (16:18) — the court for all Israel, the tribe's, the city's; the small court judges and executes as the great (the Sifrei 144:2-5; ordinances.courts('twenty_three') %s, the sizes %s by CALL): THE PARAMETER the_three_tiers; the city court that tries a capital case accepted" % (OR_23, ES_SIZES), ['accepted'])
    if ask == 'the_qualified_judge':
        ink('16:18', '"and they shall judge the people with RIGHTEOUS JUDGMENT" — the verse\'s last two tokens %s' % (W16(18)[-2:],))
        move('the Sifrei 144:6-11 (read whole at the reading); cold_run_opening_speech (CALL) — OP(the_qualities) = %s; OP(judge_righteously) = %s' % (OP_QUAL[:60], OP_RIGHT[:60]), "THE QUALIFIED JUDGE — 'righteous judgment' the judge's fitness (144:6-8: appoint the fit; the one who appoints an unfit judge as if he planted an asherah — 144:11 the chapter's own juxtaposition with 16:21); the seven qualities asked and the three found (1:13-15 by CALL); the appointer who sets a judge for his wealth (144:9-10)")
        dat('the qualified judge a DATA row (the_qualified_judge — the fit appointed; the appointer for wealth barred); the exam\'s person the appointer who sets a judge for his wealth — barred from it')
        return out("the qualified judge (16:18) — 'righteous judgment' the fit judge; the appointer for wealth as if he planted an asherah (the Sifrei 144:6-11; opening_speech's qualities by CALL): the appointer for wealth barred from it", ['barred_from_it'])
    if ask == 'wrest_no_judgment':
        ink('16:19', '"YOU SHALL NOT WREST JUDGMENT" — the phrase\'s three seats %s; the negations in the verse %s' % (P('לא', 'תטה', 'משפט', books=None), [x for x in W16(19) if x in NEG_T]))
        move('the Sifrei 144:8, 281:1 (read whole at the reading — 281:1 the outside row on 24:17); cold_run_ordinances (CALL) — OR.courts(poor_not_glorified) = %s; cold_run_holiness (CALL) — HO.conduct(no_favor) = %s, (five_effects) = %s' % (OR_POOR, HO_FAVOR, HO_FIVE), "WREST NO JUDGMENT — Exodus 23:6's 'you shall not wrest the judgment of your poor' and 24:17's sojourner the twins (281:1: two prohibitions for the sojourner, three for the fatherless sojourner); Leviticus 19:15's 'do no wrong in judgment' with the judge's five effects by CALL (judgment_perverted the holiness engine's heaven entry, NONE on the tape UNMOVED): THE BLOCK judgment_wresting_barred")
        dat('THE WRITE judgment_wresting_barred — a BLOCK on israel_people at the counter\'s day (DH2); the exam\'s person the judge who tilts the verdict for the poor — barred from it')
        return out("wrest no judgment (16:19) — Exodus 23:6's and 24:17's twins, Leviticus 19:15's five effects (ordinances.courts %s, holiness.conduct %s by CALL): THE WRITE judgment_wresting_barred, a BLOCK on Israel at the chapter's own day; the judge who tilts for the poor barred from it" % (OR_POOR, HO_FAVOR), ['judgment_wresting_barred'])
    if ask == 'respect_no_person':
        ink('16:19', '"YOU SHALL NOT RESPECT PERSONS" — "recognize faces" %s; 1:17\'s "you shall not respect persons in judgment" the charge\'s clause; 10:17\'s "who lifts no face" the declaration' % (W16(19)[3:6],))
        move('the Sifrei 144:9-10 (read whole at the reading); cold_run_opening_speech (CALL) — OP(no_faces) = %s; cold_run_second_tablets (CALL) — ST(lifts_no_face) = %s; cold_run_holiness (CALL) — HO.conduct(equal_treatment) = %s' % (OP_FACES[:60], ST_FACE[:50], HO_EQUAL), "RESPECT NO PERSON — the judge who lets one stand and one sit, one speak at length and one briefly (144:9 — the equal-treatment protocol by CALL); the appointer who sets a judge for his wealth (144:10); 1:17's 'no faces' befriend / estrange disputed (Sanhedrin 7b by CALL); 10:17's face a declaration about God: THE BLOCK person_respecting_barred")
        dat('THE WRITE person_respecting_barred — a BLOCK on israel_people at the counter\'s day (DH2); the exam\'s person the judge who seats one litigant and stands the other — barred from it')
        return out("respect no person (16:19) — the judge who seats one and stands the other (the Sifrei 144:9; opening_speech's no_faces and holiness's equal treatment by CALL): THE WRITE person_respecting_barred, a BLOCK on Israel at the chapter's own day; the unequal judge barred from it", ['person_respecting_barred'])
    if ask == 'take_no_bribe':
        ink('16:19', '"AND YOU SHALL NOT TAKE A BRIBE, for the bribe blinds the eyes of THE WISE and perverts the words of the righteous" — Exodus 23:8\'s seven in order %s, "the wise" here where Exodus has "the open-eyed" %s' % (TWIN['16:19 vs Exod 23:8'], ([x for x in W16(19) if x in ('חכמים', 'פקחים')], [x for x in words('Exod', 23, 8) if x in ('חכמים', 'פקחים')])))
        move('the Sifrei 144:11 (read whole at the reading); cold_run_ordinances (CALL) — OR.courts(bribe) = %s, (bribe_absolute) = %s; cold_run_second_tablets (CALL) — ST(takes_no_bribe) = %s; ST(the_permitted_fee) = %s; cold_run_holiness (CALL) — HO.conduct(bribe) = %s; the one database — bribe_barred on %s' % (OR_BRIBE, OR_ABS, ST_BRIBE[:70], ST_FEE[:50], HO_BRIBE, BRIBE_SCAN), "TAKE NO BRIBE — Exodus 23:8's BLOCK bribe_barred on the judge, DECLARED at the ordinances' cell and NEVER WRITTEN ON ANY ENTITY (DB7's declaration; 10:17 the callee's own '16:19 the command's seat forward'): WRITTEN HERE FOR THE FIRST TIME at 16:19's line — bribery absolute, even to judge truly (the Mekhilta; Ketubot 105a by the second-tablets cell); the permitted fee for evident loss the exception; the bribed judge's eyes dim (Peah 8:9 by CALL): THE REUSE bribe_barred's first entry on israel_people")
        dat('THE WRITE bribe_barred — Exodus 23:8\'s BLOCK, its FIRST entry on israel_people at the counter\'s day (DH2; DB7\'s "NEVER" 0 -> 1 retyped before the tape); the exam\'s person the judge who takes a bribe to judge truly — barred from it')
        return out("take no bribe (16:19) — Exodus 23:8's block declared and never written before, its first entry here (the Sifrei 144:11; ordinances.courts %s / %s, second_tablets and holiness by CALL): THE WRITE bribe_barred on Israel at the chapter's own day; the judge who takes a bribe to judge truly barred from it" % (OR_BRIBE, OR_ABS), ['bribe_barred'])
    if ask == 'justice_justice':
        ink('16:20', '"JUSTICE, JUSTICE YOU SHALL PURSUE" — the doubled word\'s one seat in the Bible %s; the verse\'s first three tokens %s' % (P('צדק', 'צדק', books=None), W16(20)[:3]))
        move('the Sifrei 144:12 (read whole at the reading); cold_run_ordinances (CALL) — OR.courts(one_vs_two) = %s, (asymmetry) = %s, (dissenter) = %s' % (OR_ONE_TWO, OR_ASYM, OR_DISS), "JUSTICE, JUSTICE — one who left the court acquitted is not brought back to conviction (144:12 — the doubled word read as two rules: THE ACQUITTAL FINAL); Mishnah Sanhedrin 4:1 by CALL — money cases tilt by one either way, capital cases by one for merit and two for liability, reversed for merit not for liability; acquit by one, convict by two (the Mekhilta): A PARAMETER the_acquittal_final; THE STATUS justice_pursuit_commanded")
        dat('THE WRITE justice_pursuit_commanded — a STATUS on israel_people at the counter\'s day (DH2); THE PARAMETER the_acquittal_final (the answer sheet by CALL); the exam\'s person the court that reopens an acquittal to convict — barred from it')
        return out("justice, justice (16:20) — the acquittal final, one who left acquitted not returned to conviction (the Sifrei 144:12; ordinances.courts('one_vs_two') %s by CALL): THE WRITE justice_pursuit_commanded, a STATUS on Israel at the chapter's own day; the court that reopens an acquittal to convict barred from it" % (OR_ONE_TWO,), ['justice_pursuit_commanded'])
    if ask == 'that_you_may_live':
        ink('16:20', '"THAT YOU MAY LIVE AND INHERIT the land which the LORD your God gives you" — the clause\'s one seat in this form %s; 4:1\'s six in order %s' % (P('למען', 'תחיה', 'וירשת', books=None), TWIN['16:20 vs 4:1']))
        move('the Sifrei 144:13 (read whole at the reading)', "THAT YOU MAY LIVE AND INHERIT — the appointment of fit judges keeps Israel alive and settles them on their land (144:13): the ground of the courts' law, a DATA row (4:1's 'that you may live and go in and possess' the twin)")
        dat('the ground a DATA row (that_you_may_live — the courts the land\'s condition); the exam\'s person the city that appoints fit judges — accepted')
        return out("that you may live (16:20) — fit judges keep Israel alive and settled on their land (the Sifrei 144:13): the city that appoints fit judges accepted", ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_asherah_and_the_pillar(case, data):
    """F6 — Deut 16:21-22 — THE LINE asherah_and_pillar_barred writing asherah_beside_the_altar_barred and pillar_barred (BLOCKS); the pillars' change of state read from the tape's own entries; the objects' kin by CALL (erection, seven_nations, place_name, journeys)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_asherah_beside_the_altar':
        ink('16:21', '"YOU SHALL NOT PLANT FOR YOURSELF AN ASHERAH of any tree BESIDE THE ALTAR of the LORD your God" — the asherah bare here and at Exodus 34:13 alone %s; 7:5 and 12:3 share nothing in order with 16:21 (asserted at the reading)' % (U('אשרה', 'אשריו', 'אשרים', books=T),))
        move('the Sifrei 145:1-3 (read whole at the reading — 145:3 reread from chapter 12); cold_run_erection (CALL) — ER.covenant(sheet_az_3_5) = %s; cold_run_seven_nations (CALL) — SN(the_asherah_shade) = %s; SN(the_asherah_wood) = %s; cold_run_place_name (CALL) — PN(the_three_asherim) = %s' % (ER_MADE, SN_SHADE[:50], SN_WOOD[0][:50], PN_ASHERIM[:50]), "THE ASHERAH BESIDE THE ALTAR — the planting's own prohibition (145:1-2) and the a fortiori: if the asherah beside the altar, which the Torah permits elsewhere as a tree, is barred, how much more idolatry (145:3 — the spine's own reading); the asherah forbidden because a hand made it (Mishnah Avodah Zarah 3:5 by CALL); the shade not sat in, the wood's user lashed (7:5's cells by CALL); the three asherim (12:3 by CALL): THE BLOCK asherah_beside_the_altar_barred")
        dat('THE WRITE asherah_beside_the_altar_barred — a BLOCK on israel_people at the counter\'s day (DH2); the exam\'s person the one who plants a tree beside the altar — barred from it')
        return out("the asherah beside the altar (16:21) — the planting barred and the a fortiori (the Sifrei 145:1-3; erection's %s, seven_nations' shade and wood, place_name's three asherim by CALL): THE WRITE asherah_beside_the_altar_barred, a BLOCK on Israel at the chapter's own day; the planter beside the altar barred from it" % (ER_MADE,), ['asherah_beside_the_altar_barred'])
    if ask == 'any_tree':
        ink('16:21', '"an asherah OF ANY TREE beside the altar … which you shall make for yourself" — "any tree" %s; the altar "which you shall make" the altar\'s own law (Exodus 20:21-23 by name)' % (W16(21)[4:6],))
        move('the Sifrei 145:4 (read whole at the reading)', "ANY TREE — even a house of wood beside the altar in the shelf's reading (145:4: whence that one who builds a wooden house on the Temple mount transgresses? 'any tree'): a DATA row; the altar's own law Exodus 20:21-23's (the earthen altar, the hewn stones)")
        dat('any tree a DATA row (any_tree — the wooden house included); the exam\'s person the one who builds a wooden structure beside the altar — barred from it')
        return out("any tree (16:21) — even a wooden house beside the altar (the Sifrei 145:4): the builder of a wooden structure beside the altar barred from it", ['barred_from_it'])
    if ask == 'the_pillar_hated':
        ink('16:22', '"AND YOU SHALL NOT SET UP FOR YOURSELF A PILLAR, WHICH THE LORD YOUR GOD HATES" — 12:31\'s "hates" shared %s; the pillar at eleven Torah seats (Jacob\'s six, Sinai\'s, the ban\'s — asserted at the reading); no kin by shared tokens (KINC[22] empty %s)' % (TWIN['16:22 vs 12:31'], KINC[22] == []))
